\newcommand{\XX}{\R^n}
\newcommand{\YY}{\R^m}


\begin{equation}
    \minimize_{x}
    {}\quad{}
    q(x) \coloneqq f(x) + g(x)
    {}\qquad{}
    \stt
    {}\quad{}
    c(x) \in D ,
    \tag{P}\label{eq:P}
\end{equation}

where $x$ is the decision variable, $f$ and $c$ are smooth functions, $g$ is proper and lower semicontinuous, and $D$ is a nonempty closed set.


\begin{ass}\label{ass:P}
		The following hold in \eqref{eq:P}:
		\begin{enumerate}
			\item\label{ass:f}%
				$\func{f}{\XX}{\R}$ and $\func{c}{\XX}{\YY}$ are continuously differentiable with locally Lipschitz continuous derivatives;
			\item\label{ass:g}%
				\(\func{g}{\XX}{\Rinf}\) is proper, lower semicontinuous and prox-bounded;
			\item\label{ass:set}%
				\(D\subset \YY\) is a nonempty and closed set.
		\end{enumerate}
	\end{ass}

The effective domain of an extended real-valued function $\func{h}{\R^n}{\Rinf}$ is denoted by $\dom h \coloneqq \{x\in\R^n \suchthat h(x) < \infty \}$.
We say that $h$ is \emph{proper} if $\dom h \neq \emptyset$
and \emph{lower semicontinuous} (lsc) if $h(\bar{x}) \leq \liminf_{x\to\bar{x}} h(x)$ for all $\bar{x} \in \R^n$.


% subgradient
Given a proper and lsc function $\func{h}{\XX}{\Rinf}$ and a point $\bar{x}\in\dom h$, we may avoid to assume $h$ continuous and instead appeal 
to $h$-\emph{attentive} convergence of a sequence $\{ x^k \}$:
\begin{equation}
x^k \toattentive{h} \bar{x}
{}\quad:\Leftrightarrow\quad{}
x^k \to \bar{x}
{}\quad\text{with}\quad{}
h(x^k) \to h(\bar{x}) .
\end{equation}
Following \cite[Def. 8.3]{rockafellar1998variational}, we denote by $\ffunc{\hat{\partial} h}{\XX}{\XX}$ the \emph{regular subdifferential} of $h$, where
\begin{equation}
v \in \hat{\partial} h(\bar{x})
{}\quad:\Leftrightarrow\quad{}
\liminf_{\substack{x\to\bar{x}\\x\neq\bar{x}}} \frac{h(x) - h(\bar{x}) - \langle v, x-\bar{x}\rangle}{\|x-\bar{x}\|} \geq 0 .
\end{equation}
The (limiting) \emph{subdifferential} of $h$ is $\ffunc{\partial h}{\XX}{\XX}$, where $v \in \partial h(\bar{x})$ if and only if there exist sequences $\{x^k\}$ and $\{v^k\}$ such that $x^k \toattentive{h} \bar{x}$ and $v^k \in \hat{\partial} h(x^k)$ with $v^k \to v$.
The subdifferential of $h$ at $\bar{x}$ satisfies $\partial(h+h_0)(\bar{x}) = \partial h(\bar{x}) + \nabla h_0(\bar{x})$ for any $\func{h_0}{\XX}{\Rinf}$ continuously differentiable around $\bar{x}$ \cite[Ex. 8.8]{rockafellar1998variational}.
For formal completeness, we set $\hat{\partial} h(\bar{x})\coloneqq\partial h(\bar{x})\coloneqq\emptyset$ for each $\bar{x}\notin\dom h$.


Furthermore, we say that $x^\ast \in \XX$ is \emph{$\varepsilon$-stationary} for some $\varepsilon \geq 0$ if
\begin{equation}
	\exists \eta \in \partial h(x^\ast) \colon \|\eta\| \leq \varepsilon .
	\label{eq:epsstationary}
\end{equation}


If $S(\bar{x})$ is nonempty, we define the \emph{outer limit} of $S$ at $\bar{x}$
by means of
\begin{align*}
	\limsup\limits_{x\to\bar{x}} S(x)
	\coloneqq
	\{
		y\in\YY
		\suchthat
		\exists x^k\to\bar{x},\,
		\exists y^k\to y,\,
		y^k\in S(x^k)\,\forall k\in\N
	\}
\end{align*}
and note that this is a closed superset of $S(\bar{x})$ by definition.


% Prox-boundedness
and we say that $h$ is \emph{prox-bounded} if it is proper and $h + \|\cdot\|^2 / (2\gamma)$ is bounded below on $\XX$ for some $\gamma > 0$.
The supremum of all such $\gamma$ is the threshold $\gamma_h$ of prox-boundedness for $h$.


The \emph{projection} mapping $\proj_D$ and the \emph{distance} function $\dist_D$ are defined by
\begin{equation*}
	\proj_D(v)
	{}\coloneqq{}
	\argmin_{z \in D} \|z - v\|
	{}\quad\text{and}\quad{}
	\dist_D(v)
	{}\coloneqq{}
	\inf_{z \in D} \|z - v\| .
\end{equation*}
The former is a set-valued mapping whenever $D$ is nonconvex, whereas the latter is always single-valued.


The \emph{indicator} function of a set $D \subset \YY$ is the function $\func{\indicator_D}{\YY}{\Rinf}$ defined as $\indicator_D(v) = 0$ if $v \in D$, and $\indicator_D(v) = \infty$ otherwise.
If $D$ is nonempty and closed, then $\indicator_D$ is proper and lsc.


Given $z \in D$, the \emph{limiting normal cone} to $D$ at $z$ is the closed cone
\begin{equation*}
	\limnormalcone_D(z) \coloneqq \limsup_{v \to z} \; \cone \left( v - \proj_D(v) \right) .
\end{equation*}
For $\tilde z\notin D$, we formally set $\limnormalcone_D(\tilde z):=\emptyset$.


\begin{defin}[Feasibility]\label{def:feasible}
		A point $x^\ast \in \XX$ is called \emph{feasible} for \eqref{eq:P} 
		if $x^\ast \in \dom q$ and $c(x^\ast) \in D$.
	\end{defin}

\begin{defin}[AM-stationarity]\label{def:AMstationary}
		Let $x^\ast \in \XX$ be a feasible point for \eqref{eq:P}.
		Then, $x^\ast$ is called an \emph{asymptotically M-stationary} point of \eqref{eq:P} 
		if there exist sequences $\{x^k\}, \{\eta^k\} \subset \XX$ and 
		$\{y^k\}, \{\zeta^k\} \subset \YY$ such that 
		$x^k \toattentive{q} x^\ast$, $\eta^k \to 0$, $\zeta^k \to 0$ and
		\begin{subequations}
			\begin{align}
				-\nabla c(x^k)^\top y^k + \eta^k
				{}\in{}&
				\partial q(x^k) ,
				\label{eq:AMstationary:x} \\
				y^k 
				{}\in{}&
				\limnormalcone_D( c(x^k) + \zeta^k )
				\label{eq:AMstationary:y}
			\end{align}
			\label{eq:AMstationary}
		\end{subequations}
		for all $k \in \N$.
	\end{defin}

\begin{equation}
	\minimize_{x ,\; s}
	{}\quad{}
	q(x)
	{}\qquad{}
	\stt
	{}\quad{}
	c(x) - s = 0
	,\quad
	s \in D .
	\tag{P$_{\text{S}}$}\label{eq:ALMz:P}
\end{equation}

For some penalty parameter $\mu>0$,
let us define the $\mu$-augmented Lagrangian function $\func{\LLslack_\mu}{\XX \times \YY \times \YY}{\Rinf}$ associated to \eqref{eq:ALMz:P} as
\begin{align}
	\LLslack_\mu(x,s,y)
	{}\coloneqq{}&
	q(x) + \indicator_D(s) + \innprod{y}{c(x) - s} + \frac{1}{2\mu} \| c(x) - s \|^2 \nonumber \\
	{}={}&
	q(x) + \indicator_D(s) + \frac{1}{2\mu} \| c(x) + \mu y - s \|^2 - \frac{\mu}{2}\|y\|^2 .
	\label{eq:Lz}
\end{align}

For later use, let us compute the subdifferential of $\LLslack_\mu$ with respect to the
variables $x$ and $s$:
\begin{subequations}
	\label{eq:dLS}


\begin{align}
		\partial_x \LLslack_\mu(x,s,y) 
		{}={}&
		\partial q(x) + \frac{1}{\mu} \nabla c(x)^\top [c(x) + \mu y - s] ,
		\label{eq:dxLS} \\
		\partial_s \LLslack_\mu(x,s,y) 
		{}={}&
		\limnormalcone_D(s) - \frac{1}{\mu} [c(x) + \mu y - s] .
		\label{eq:dzLS}
	\end{align}

\begin{algorithm}[t]
	\caption{Augmented Lagrangian method for \eqref{eq:P}}%
	\label{alg:ALM}%
	\begin{algorithmic}[1]%
	\linespread{1.2}\selectfont%
	%
	%
%	\Require $x^0 \in \XX$, $y^0 \in \YY$ %$\varepsilon_{\text{tol}} \geq 0$
	\Initialize Select $\mu_0 > 0$, $\theta,\kappa \in(0,1)$ and $\Ybounded \subset \YY$ nonempty bounded
	\item[For \(k=0,1,2\ldots\)]
	\State\label{state:ALM:init}\label{state:ALM:ysafe}%
		Select $\hat{y}^k \in \Ybounded$ and $\varepsilon_k \geq 0$
	\State\label{state:ALM:subproblem}%\label{state:ALM:z}%
		Compute an $\varepsilon_k$-stationary point $(x^k,s^k)\in\XX\times D$ of $\LL_{\mu_k}^{\text{S}}(\cdot,\cdot,\hat{y}^k)$
	\State\label{state:ALM:y}%
		Set $y^k \gets \hat{y}^k + [ c(x^k) - s^k ] / \mu_k$
%	\If{$\varepsilon_{k+1} \leq \varepsilon_{\text{tol}}$ and $\|c(x^{k+1}) - z^{k+1}\| \leq \varepsilon_{\text{tol}}$}\label{state:ALM:ifend}%
%		\State\label{state:ALM:end}%
%			\algfont{return} $(x^{k+1}, y^{k+1})$
%	\EndIf
	\If{$k = 0$ or $\| c(x^k) - s^k \| \leq \theta \, \| c(x^{k-1}) - s^{k-1} \|$}\label{state:ALM:if}
		\State\label{state:ALM:ifpassed}%
			Set $\mu_{k+1} \gets \mu_k$
	\Else
		\State\label{state:ALM:iffailed}%
			Select $\mu_{k+1} \in (0, \kappa \mu_k]$
	\EndIf
\end{algorithmic}
%
\end{algorithm}

	Throughout our convergence analysis, we assume that \cref{alg:ALM} is well-defined, 
thus requiring that each subproblem at \cref{state:ALM:subproblem} admits an approximate stationary point.
Moreover, the following statements assume the existence of some accumulation point $x^\ast$ 
or $(x^\ast,s^\ast)$
for a sequence $\{ x^k \}$ or $\{(x^k,s^k)\}$, respectively, generated by \cref{alg:ALM}.

